// Kit tag plan for XB Kit Re-tagger (#269). Reads only the outputs of earlier nodes; makes no HTTP
// call, reads no environment value and never sees a secret except to check the token step worked.
// 1. Refuse (no writes, one ERROR alert) when the token step failed, any product page failed, was
//    throttled or has no data, the read stopped early, or the products scanned differ from Shopify's
//    count of active products.
// 2. For each active product, work out the kit tags it should have from RULES (XT rules v1, logic
//    fields only; a rules change is a reviewed repo PR, never fetched at run time).
// 3. Only the 30 known tags (kit-<kit>, ks-<slot>) are ever added or removed. kit-no, kit-pin-<kit>,
//    unknown kit-/ks- tags and every other tag are never touched.
// 4. Decide the run mode: failed, dry_run, no_change, over_cap or write (see Run Settings).
// Partner logic (clause match, exclude words, kit-no, kit-pin-<kit>) is kept unchanged in behaviour.
const RULES = {"slots":{"merino_base":{"any":[{"vendor":["Icebreaker","Smartwool"],"not_type":["Socks","Dress","Skirt","Bra","Underwear"]},{"tag":["Base Layer","MerinoLOFT","ZEO-LINE"]}]},"cool_layer":{"any":[{"tag":["Keep Cool","Quick Dry","UV Protection","Breathable"],"type":["T-Shirt","T-shirt","Shirt","Pants","Shorts","Arm Cover","Hat","Cap","Headwear"]}]},"insulation":{"any":[{"tag":["Down","Down Jacket","Insulated Jacket","Synthetic Insulation","PrimaLoft","EXCELOFT","Insulation","Realfleece"],"type":["Jacket","Vest","Coat"]}]},"light_insul":{"any":[{"tag":["EXCELOFT","Realfleece","Synthetic Insulation","Soft Shell"],"type":["Jacket","Vest","Sweatshirt"]},{"tag":["Down"],"title":["superior","ex light","plasma","u.l."]}]},"shell":{"any":[{"tag":["Rain Jacket","Waterproof Shell","GORE-TEX","Rain Gear","Rain Gears","Rain Pants","DRY-TEC"]},{"type":["Rain Coat","Rain Pants","Rain Poncho","Backpack Rain Cover"]}]},"warm_acc":{"any":[{"type":["Gloves","Beanie"]},{"tag":["Balaclava","Keep Warm"],"type":["Gloves","Beanie","Headwear","Accessories","Accessory"]},{"vendor":["Hothands"]}]},"socks":{"any":[{"type":["Socks"]}]},"poles":{"any":[{"type":["Trekking Poles","Hiking Pole"]},{"tag":["Trekking Poles","Hiking Pole"]}]},"light":{"any":[{"type":["Headlamp","Lights"]},{"tag":["Headlamp","Torch Light","Lanterns"]}]},"tool_trail":{"any":[{"vendor":["Leatherman"],"tag":["lm-multi-tool","lm-keychain"]}]},"tool_edc":{"any":[{"vendor":["Leatherman"],"tag":["lm-edc","lm-keychain"]}]},"power":{"any":[{"vendor":["BioLite"]}]},"sleep":{"any":[{"type":["Sleeping Bag","Sleeping Bag Liners","Sleeping","Sleep","Travel Pillow"]}]},"pack_day":{"any":[{"type":["Backpack"],"tag":["Daypack","20-28L","30L"]}]},"pack_trek":{"any":[{"type":["Backpack"],"tag":["30L","40L","50-55L","60-65L"]},{"tag":["Luggage and Duffle"]}]},"hydration":{"any":[{"type":["Bottle","Water Pack","Water Tube","Bottle Accessories"]},{"tag":["Hydration"]}]},"kolon":{"any":[{"vendor":["Kolon Sport"]}]},"travel":{"any":[{"type":["Travel Accessories","Travel accessories","Wallet","Lock","Travel Pillow","Bags"]},{"tag":["Travel kit","Travel/Packable","Travel / Packable","packable"],"type":["Jacket","Bags","Shirt","Pants","Travel Accessories"]}]},"alpine":{"any":[{"tag":["Alpine","Expedition","Climbing"]},{"type":["Crampon","Ice Axe","Climbing Accessories","Helmet","Carabiner"]}]},"water":{"any":[{"tag":["Water Sport","Diving","Sandals"]},{"type":["Towel"]}]},"bike":{"any":[{"tag":["Cycling","Bicycle","Bicycle Accessories"]},{"type":["Bicycle Accessories","Bicycle Tools","Helmet"]}]},"footwear":{"any":[{"type":["Footwear","Shoes"],"not_tag":["Sandals"]},{"tag":["Shoes"],"not_tag":["Sandals"]}]}},"profiles":{"tropical":{"slots":["cool_layer","shell","socks","poles","light","tool_trail","hydration","pack_day","footwear"]},"hut":{"slots":["merino_base","light_insul","shell","socks","poles","light","tool_trail","pack_day","hydration","kolon","footwear"]},"himalaya":{"slots":["merino_base","insulation","shell","warm_acc","socks","poles","light","tool_trail","sleep","pack_trek","hydration","power","kolon"]},"expedition":{"slots":["merino_base","insulation","shell","warm_acc","socks","light","tool_trail","sleep","pack_trek","power","alpine"]},"winter":{"slots":["merino_base","insulation","shell","warm_acc","socks","light","power","kolon","footwear"]},"travel":{"slots":["travel","cool_layer","merino_base","shell","socks","tool_edc","kolon","pack_day"]},"island":{"slots":["water","cool_layer","hydration","tool_edc","pack_day"]},"ride":{"slots":["bike","cool_layer","shell","tool_trail","light","hydration"]}},"exclude":{"title_words":["kid","kids","kid's","kids'","junior","toddler","baby","baby's","boxer","boxers","brief","briefs","bikini","thong","bra","bralette","hipster","panty","panties"],"types":["Underwear","Bra"]}};
const ADD_ONLY = 'mutation KitTagsAdd($id: ID!, $add: [String!]!) { add: tagsAdd(id: $id, tags: $add) { node { id } userErrors { field message } } }';
const REMOVE_ONLY = 'mutation KitTagsRemove($id: ID!, $remove: [String!]!) { remove: tagsRemove(id: $id, tags: $remove) { node { id } userErrors { field message } } }';
const ADD_AND_REMOVE = 'mutation KitTagsChange($id: ID!, $add: [String!]!, $remove: [String!]!) { add: tagsAdd(id: $id, tags: $add) { node { id } userErrors { field message } } remove: tagsRemove(id: $id, tags: $remove) { node { id } userErrors { field message } } }';
const GID_RE = /^gid:\/\/shopify\/Product\/[0-9]{1,20}$/;
const MAX_LIST = 25;

const settings = $('Run Settings').first().json;
const token = $('Get Shopify Access Token').first().json;
const pages = $input.all().map((item) => item.json);
const sgtDate = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10);

const norm = (s) => (typeof s === 'string' ? s : '').trim().toLowerCase();
const safe = (s) => norm(s).replace(/[^a-z0-9._-]/g, '?').slice(0, 80);
const KITS = Object.keys(RULES.profiles);
const KNOWN = new Set([...KITS.map((k) => 'kit-' + k), ...Object.keys(RULES.slots).map((s) => 'ks-' + s)]);
const managed = (tag) => KNOWN.has(norm(tag));
const looksManaged = (tag) => {
  const x = norm(tag);
  return (x.startsWith('kit-') || x.startsWith('ks-')) && x !== 'kit-no' && !x.startsWith('kit-pin-');
};

const httpCode = (error) => {
  const text = typeof error === 'string' ? error : JSON.stringify(error || '');
  const match = /\b([45][0-9][0-9])\b/.exec(text);
  return match ? 'http_' + match[1] : 'request_error';
};
const pageProblem = (page) => {
  if (!page || typeof page !== 'object') return 'no_page';
  if (page.error !== undefined) return httpCode(page.error);
  if (Array.isArray(page.errors) && page.errors.length) {
    return page.errors.some((e) => e && e.extensions && e.extensions.code === 'THROTTLED') ? 'throttled' : 'graphql_errors';
  }
  const products = page.data && page.data.products;
  if (!products || !Array.isArray(products.nodes) || !products.pageInfo) return 'no_data';
  return '';
};

const failed = (key, lines) => [{ json: { mode: 'failed', writes: [], alert: {
  severity: 'ERROR', key, short: key,
  lines: ['Kit re-tagger ' + sgtDate + ': ' + key + '. Nothing was written.', ...lines,
    'Next: the next daily run tries again. If it repeats, open n8n and run XB Kit Re-tagger by hand with DRY_RUN on.'],
} } }];

// ---- 1. the token and the read ---- //
if (!token || token.error !== undefined || typeof token.access_token !== 'string' || token.access_token.length < 10) {
  return failed('token_failed', ['Token request: ' + (token && token.error !== undefined ? httpCode(token.error) : 'no_token')]);
}
if (pages.length === 0) return failed('read_failed', ['Product read: no_page']);
for (let i = 0; i < pages.length; i += 1) {
  const problem = pageProblem(pages[i]);
  if (problem) return failed('read_failed', ['Product read: ' + problem + ' on page ' + (i + 1) + ' of ' + pages.length]);
}
const last = pages[pages.length - 1].data.products.pageInfo;
const count = pages[0].data.productsCount;
const products = pages.flatMap((page) => page.data.products.nodes);
const ids = new Set(products.map((p) => p && p.id));
const incomplete = [];
if (last.hasNextPage !== false) incomplete.push('read stopped at the page limit (' + pages.length + ' pages)');
if (!count || typeof count.count !== 'number' || count.precision !== 'EXACT') incomplete.push('no exact active product count');
else if (count.count !== products.length) incomplete.push('scanned ' + products.length + ' of ' + count.count + ' active products');
if (ids.size !== products.length) incomplete.push('duplicate or missing product ids');
const bad = products.filter((p) => !p || !GID_RE.test(p.id) || !Array.isArray(p.tags) || p.status !== 'ACTIVE');
if (bad.length) incomplete.push(bad.length + ' product rows with a bad id, tag list or status');
if (incomplete.length) return failed('read_incomplete', incomplete.map((reason) => 'Product read: ' + reason));

// ---- 2. desired kit tags (partner logic) ---- //
function clauseMatch(c, v, t, tags, title) {
  const tg = new Set(tags.map(norm));
  if (c.vendor && !c.vendor.map(norm).includes(norm(v))) return false;
  if (c.type && !c.type.map(norm).includes(norm(t))) return false;
  if (c.not_type && c.not_type.map(norm).includes(norm(t))) return false;
  if (c.tag && !c.tag.map(norm).some((x) => tg.has(x))) return false;
  if (c.not_tag && c.not_tag.map(norm).some((x) => tg.has(x))) return false;
  if (c.title && !c.title.map(norm).some((x) => norm(title).includes(x))) return false;
  return true;
}
function excluded(p) {
  const ex = RULES.exclude || {};
  if ((ex.types || []).map(norm).includes(norm(p.productType))) return true;
  const words = (ex.title_words || []).map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  return words.length > 0 && new RegExp("(?<![\\w'])(" + words.join('|') + ")(?![\\w'])", 'i').test(p.title || '');
}
function desired(p) {
  const tg = new Set(p.tags.map(norm));
  if (tg.has('kit-no') || p.status !== 'ACTIVE' || excluded(p)) return new Set();
  const slots = Object.entries(RULES.slots)
    .filter(([, s]) => s.any.some((c) => clauseMatch(c, p.vendor, p.productType, p.tags, p.title)))
    .map(([k]) => k);
  const out = new Set();
  const used = new Set();
  for (const [name, prof] of Object.entries(RULES.profiles)) {
    if (prof.slots.some((s) => slots.includes(s)) || tg.has('kit-pin-' + name)) {
      out.add('kit-' + name);
      prof.slots.forEach((s) => used.add(s));
    }
  }
  slots.filter((s) => used.has(s)).forEach((s) => out.add('ks-' + s));
  return out;
}

const changes = [];
const unknown = new Set();
for (const p of products) {
  p.tags.filter((t) => looksManaged(t) && !managed(t)).forEach((t) => unknown.add(safe(t)));
  const want = desired(p);
  const have = new Set(p.tags.filter(managed).map(norm));
  const add = [...want].filter((t) => !have.has(t)).sort();
  const remove = p.tags.filter((t) => managed(t) && !want.has(norm(t)));
  if (add.length || remove.length) changes.push({ id: p.id, handle: safe(p.handle), add, remove });
}

// ---- 3. counts, caps and the run mode ---- //
const kitRemovals = changes.filter((c) => c.remove.some((t) => norm(t).startsWith('kit-'))).length;
const perKit = KITS.map((k) => {
  const plus = changes.filter((c) => c.add.includes('kit-' + k)).length;
  const minus = changes.filter((c) => c.remove.some((t) => norm(t) === 'kit-' + k)).length;
  return plus || minus ? 'kit-' + k + ' +' + plus + ' -' + minus : '';
}).filter(Boolean);
const changeCap = Number(settings.CHANGE_CAP);
const removeCap = Number(settings.REMOVE_CAP);
if (!Number.isInteger(changeCap) || changeCap < 1 || !Number.isInteger(removeCap) || removeCap < 0) {
  return failed('unexpected', ['Run Settings: CHANGE_CAP and REMOVE_CAP must be whole numbers']);
}
const overCap = changes.length > changeCap || kitRemovals > removeCap;
const override = settings.CAP_OVERRIDE === true;
const dryRun = settings.DRY_RUN !== false;

const counts = [
  'Active products scanned: ' + products.length + '. Products to change: ' + changes.length
    + ' (cap ' + changeCap + '). Products losing a kit tag: ' + kitRemovals + ' (cap ' + removeCap + ').',
  'Tags to add: ' + changes.reduce((n, c) => n + c.add.length, 0)
    + '. Tags to remove: ' + changes.reduce((n, c) => n + c.remove.length, 0) + '.',
  ...(perKit.length ? ['Per kit: ' + perKit.join(', ')] : []),
  ...(unknown.size ? ['Unknown kit-/ks- tags left alone: ' + [...unknown].sort().slice(0, 10).join(' ')] : []),
];
const handleLines = (limit) => {
  const shown = changes.slice(0, limit).map((c) => ('- ' + c.handle + ' ' + [...c.add.map((t) => '+' + t),
    ...c.remove.map((t) => '-' + norm(t))].join(' ')).slice(0, 300));
  return changes.length > limit ? [...shown, '... and ' + (changes.length - limit) + ' more'] : shown;
};
const fit = (head, limit, tail) => {
  for (let n = limit; n >= 0; n -= 1) {
    const lines = [...head, ...(changes.length ? [''] : []), ...handleLines(n), ...(tail.length ? ['', ...tail] : [])];
    if (lines.length <= 30 && lines.join('\n').length <= 4000) return lines;
  }
  return [...head, ...tail].slice(0, 30);
};
const writes = changes.map((c) => ({
  id: c.id,
  handle: c.handle,
  query: c.add.length && c.remove.length ? ADD_AND_REMOVE : (c.add.length ? ADD_ONLY : REMOVE_ONLY),
  variables: { id: c.id, ...(c.add.length ? { add: c.add } : {}), ...(c.remove.length ? { remove: c.remove } : {}) },
}));
const summary = { scanned: products.length, changed: changes.length, kit_removals: kitRemovals };

if (dryRun) {
  const capNote = overCap
    ? (override ? 'Over the cap, but CAP_OVERRIDE is on: a real run would write these.' : 'Over the cap: a real run would write nothing and send a change_cap warning.')
    : 'Within the cap: a real run would write these.';
  return [{ json: { mode: 'dry_run', summary, writes: [], alert: { severity: 'INFO', key: 'daily_summary',
    short: 'DRYRUN ' + sgtDate,
    lines: fit(['Kit re-tagger DRY RUN ' + sgtDate + ': nothing was written.', ...counts, capNote], MAX_LIST,
      ['To write: set DRY_RUN to false in Run Settings for one manual run (owner OK).']) } } }];
}
if (changes.length === 0) return [{ json: { mode: 'no_change', summary, writes: [], alert: null } }];
if (overCap && !override) {
  return [{ json: { mode: 'over_cap', summary, writes: [], alert: { severity: 'WARN', key: 'change_cap', short: 'change_cap',
    lines: fit(['Kit re-tagger ' + sgtDate + ': over the change cap, nothing was written.', ...counts], 20,
      ['Next: run it by hand with DRY_RUN on and check the list. If it is right, the owner sets CAP_OVERRIDE to true for one manual run.']) } } }];
}
return [{ json: { mode: 'write', summary, writes, alert: null } }];

// Check every tag write of this run (#269). One result item per write, in the same order as List
// Writes (Write Tag Changes continues on its regular output, so a failed request is an item carrying
// `error` in the same place). A write counts as done only when Shopify answered with data for every
// part (add, remove) it asked for and no userErrors. HTTP errors, GraphQL errors (THROTTLED included), missing
// data and any userErrors count as failed, each with a closed code. Output: one alert request, the
// CHANGED report when all went through, or one write_failed ERROR alert.
const writes = $('List Writes').all().map((item) => item.json);
const results = $input.all().map((item) => item.json);
const sgtDate = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10);
const summary = $('Work Out Kit Tag Changes').first().json.summary || {};

const httpCode = (error) => {
  const text = typeof error === 'string' ? error : JSON.stringify(error || '');
  const match = /\b([45][0-9][0-9])\b/.exec(text);
  return match ? 'http_' + match[1] : 'request_error';
};
const problem = (write, result) => {
  if (!result || typeof result !== 'object') return 'no_result';
  if (result.error !== undefined) return httpCode(result.error);
  if (Array.isArray(result.errors) && result.errors.length) {
    return result.errors.some((e) => e && e.extensions && e.extensions.code === 'THROTTLED') ? 'throttled' : 'graphql_errors';
  }
  if (!result.data || typeof result.data !== 'object') return 'no_data';
  for (const part of ['add', 'remove']) {
    if (!write.variables || write.variables[part] === undefined) continue;
    const answer = result.data[part];
    if (!answer || typeof answer !== 'object') return 'no_data';
    if (!Array.isArray(answer.userErrors) || answer.userErrors.length) return 'user_errors';
    if (!answer.node || answer.node.id !== write.id) return 'no_data';
  }
  return '';
};

const failures = [];
if (results.length !== writes.length) {
  failures.push({ handle: 'all', code: 'result_count_' + results.length + '_of_' + writes.length });
} else {
  writes.forEach((write, i) => {
    const code = problem(write, results[i]);
    if (code) failures.push({ handle: write.handle, code });
  });
}
const done = results.length === writes.length ? writes.length - failures.length : 0;
const head = 'Products changed: ' + done + ' of ' + writes.length + ' (active products scanned: ' + (summary.scanned || 0) + ').';
const listed = (items, limit) => items.slice(0, limit).map((x) => ('- ' + x).slice(0, 300))
  .concat(items.length > limit ? ['... and ' + (items.length - limit) + ' more'] : []);
// The sender takes at most 30 lines and 4,000 characters: list fewer products until it fits.
const fit = (build, limit) => {
  for (let n = limit; n >= 0; n -= 1) {
    const lines = build(n);
    if (lines.length <= 30 && lines.join('\n').length <= 4000) return lines;
  }
  return build(0).slice(0, 30);
};

if (failures.length === 0) {
  return [{ json: { alert: { severity: 'INFO', key: 'daily_summary', short: 'CHANGED ' + sgtDate,
    lines: fit((n) => ['Kit re-tagger ' + sgtDate + ': kit tags written.', head, '',
      ...listed(writes.map((w) => w.handle + ' ' + [...(w.variables.add || []).map((t) => '+' + t),
        ...(w.variables.remove || []).map((t) => '-' + String(t).toLowerCase())].join(' ')), n)], 25) } } }];
}
return [{ json: { alert: { severity: 'ERROR', key: 'write_failed', short: 'write_failed',
  lines: fit((n) => ['Kit re-tagger ' + sgtDate + ': some tag writes failed.', head, 'Failed: ' + failures.length + '.', '',
    ...listed(failures.map((f) => f.handle + ' ' + f.code), n), '',
    'Next: the next daily run retries them (tag writes are safe to repeat). If it repeats, run it by hand with DRY_RUN on.'], 20) } } }];
